# Afficher les icones dans le JSX
content = content.replace(
    "{open ? <span style={{ fontSize: 16 }}>{item.icon}</span> : <span style={{ fontSize: 16 }}>{item.icon}</span>}",
    "<span dangerouslySetInnerHTML={{__html: item.icon}} style={{ display: 'flex', alignItems: 'center' }} />"
)

with open('src/components/layout/SidebarLayout.tsx', 'w', encoding='utf-8') as f:
    f.write(content)
